        {"unit": "BUNIT97", "title": "My Business Legacy", "canDo": "I can talk about business legacy", "dialoguePlace": "Home", "readingText": "Business legacy is what remains after you. Not money. Not houses. But what you taught, what you built, who you helped in business. My grandmother left business stories. My mother left kindness in business. What will I leave? I want to leave a Business English school for East African adults. That is my business legacy.", "readingWords": 60, "vocab": ["Legacy", "Remains", "Taught", "Built", "Business"], "grammar": "What will I leave?", "tryAtHome": "Write your business legacy sentence"},
        {"unit": "BUNIT98", "title": "Writing a Business Book", "canDo": "I can plan a business book", "dialoguePlace": "Writer Room", "readingText": "Mary wants to write a business book: Business English for East African Adults. Chapter 1: Hello, My Job. Chapter 2: My Company. Chapter 3: My Business Region. She will write one page per day. In 100 days, she will have 100 pages. Writing a business book needs discipline, not talent. Start with one page. John will help with business chapter.", "readingWords": 64, "vocab": ["Chapter", "Discipline", "Talent", "Page", "Business"], "grammar": "She will write...", "tryAtHome": "Write 1 page of your business book"},
        {"unit": "BUNIT99", "title": "Mentoring Business Youth", "canDo": "I can mentor business youth", "dialoguePlace": "Youth Center", "readingText": "A business mentor guides, not controls. John mentors younger business adults in Nairobi. He listens to their fears. He shares his mistakes. He encourages them. He says: I was like you. You can do business. Mentoring multiplies hope. One mentor can change 100 businesses. Mary mentors young business teachers in Arusha.", "readingWords": 60, "vocab": ["Mentor", "Guides", "Encourages", "Multiplies", "Business"], "grammar": "A mentor guides...", "tryAtHome": "Mentor 1 younger business adult"},
        {"unit": "BUNIT100", "title": "Isomero Business Vision - EAC", "canDo": "I can present business vision", "dialoguePlace": "Isomero Office - Arusha", "readingText": "Isomero means learning. Our business vision: Every East African adult speaks Business English with confidence. We will build apps, clubs, and schools for business. We will train business teachers. We will use Swahili to teach Business English. We will keep culture. We will open business doors. Isomero is not just an app. It is a business movement. From Burundi to Somalia, we are one business. Mary and John lead it.", "readingWords": 66, "vocab": ["Vision", "Confidence", "Movement", "Train", "Business"], "grammar": "Our vision: Every adult...", "tryAtHome": "Present Isomero business vision"},
        {"unit": "BUNIT101", "title": "Global Business Speaker", "canDo": "I can speak globally for business", "dialoguePlace": "TED Stage", "readingText": "Hello, world. I am Mary from East Africa. I am 26, a Business English teacher from Arusha. I come from hills and drums. I learned Business English in a small classroom with no internet. Today, I speak to you about business. My message is simple: Language is power. Business education is freedom. If a woman from Arusha can speak business, anyone can. Never underestimate an adult with a business book. John is with me today from Nairobi.", "readingWords": 72, "vocab": ["Global", "Underestimate", "Freedom", "Power", "Business"], "grammar": "I come from...", "tryAtHome": "Record 2 min TED business talk"},
        {"unit": "BUNIT102", "title": "Business Research Project", "canDo": "I can present business research", "dialoguePlace": "University", "readingText": "My business research asks: Does Business English help East African adults get jobs? I interviewed 50 business adults in Arusha, Nairobi and Kampala. 80% said Business English helped. 60% got better jobs and more customers. 90% want more Business English clubs. Conclusion: Business English opens opportunities. Recommendation: Teach Business English from Pre-A1 with local business stories for adults in East Africa. Data speaks.", "readingWords": 62, "vocab": ["Research", "Interviewed", "Conclusion", "Recommendation", "Business"], "grammar": "My research asks...", "tryAtHome": "Interview 3 business people"},
        {"unit": "BUNIT103", "title": "Building a Business School", "canDo": "I can plan a business school", "dialoguePlace": "Arusha", "readingText": "To build a business school, we need land, bricks, teachers, and books. But most important, we need vision. Mary and John will start with one classroom for business adults in Arusha. They will teach 30 business adults. They will use Isomero Business curriculum. One classroom can become a business school. One school can become 8 schools in 8 EAC countries.", "readingWords": 62, "vocab": ["Build", "School", "Vision", "Classroom", "Business"], "grammar": "To build a school...", "tryAtHome": "Plan your business school"},
        {"unit": "BUNIT104", "title": "Graduation - Business CEO", "canDo": "I can graduate as Business CEO", "dialoguePlace": "Graduation Hall - Arusha", "readingText": "Today we graduate! Mary and John stand on stage. They started with Hello, I Am Mary - My Job. Now they speak Business English with confidence. They can introduce business, negotiate, present, lead and build business in 8 EAC countries. From BUNIT1 to BUNIT104, they grew. You also grew. Congratulations! You are a Business CEO. You are East African. You are Isomero. Go and build business. Go and teach others. The future of East Africa business is yours.", "readingWords": 72, "vocab": ["Graduation", "Congratulations", "Confidence", "CEO", "Future"], "grammar": "We started / Now we can", "tryAtHome": "Record graduation speech - I am Business CEO"}
